export function bufferRms(buffer,start=0,seconds=buffer.duration){let sum=0,count=0;const lo=Math.max(0,Math.floor(start*buffer.sampleRate)),hi=Math.min(buffer.length,Math.ceil((start+seconds)*buffer.sampleRate));for(let c=0;c<buffer.numberOfChannels;c++){const data=buffer.getChannelData(c);for(let i=lo;i<hi;i++){sum+=data[i]*data[i];count++;}}return count?Math.sqrt(sum/count):0;}
export function openReference(d){const p=d.getProject(),engine=d.getEngine(),assets=d.getAssets(),esc=d.esc;let ref=p.reference||{gainDb:0,start:0},mixStart=Math.floor(engine.getPosition()/16);const a=()=>assets.get(ref.assetId);
 function render(){d.modal('Mix / référence',`<div class="workflow-form"><p>La référence est écoutée séparément, sans passer dans tes inserts ni dans l’export.</p><label>Charger un morceau de référence<input id="referenceFile" type="file" accept="audio/*"></label><strong>${esc(a()?.name||'Aucune référence chargée')}</strong><div class="workflow-grid"><label>Début de la référence (secondes)<input id="referenceStart" type="number" min="0" step=".1" value="${ref.start||0}"></label><label>Gain de référence (dB)<input id="referenceLevel" type="number" min="-24" max="18" step=".5" value="${ref.gainDb||0}"></label></div><div class="workflow-row"><button id="listenMix" class="outline-btn">▶ Mon mix</button><button id="listenReference" class="outline-btn" ${!a()?'disabled':''}>▶ Référence</button><button id="stopReference" class="outline-btn">Stop</button></div><button id="matchReference" class="primary-btn" ${!a()?'disabled':''}>Comparer au même niveau moyen</button><small>Mesure RMS sur quatre mesures du mix à partir du curseur et sur la même durée de référence. Gain limité à ±18 dB ; ce réglage reste modifiable.</small><output id="referenceStatus">Comparaison à partir de la mesure ${mixStart+1}.</output></div>`,'WARLIKE / MIX');
  document.getElementById('referenceFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>60*1024*1024)throw Error('Choisis une référence de moins de 60 Mo.');await engine.init();const data=await file.arrayBuffer(),buffer=await engine.ctx.decodeAudioData(data.slice(0));d.checkpoint();ref={assetId:Math.random().toString(36).slice(2,11),start:0,gainDb:0};assets.set(ref.assetId,{name:file.name,data,buffer});p.reference=ref;d.changed();render();}catch(error){d.toast(error.message);}};
  document.getElementById('referenceStart').onchange=e=>{ref.start=Math.max(0,Math.min(a()?.buffer.duration||0,Number(e.target.value)||0));p.reference=ref;d.save();};document.getElementById('referenceLevel').onchange=e=>{ref.gainDb=Math.max(-24,Math.min(18,Number(e.target.value)||0));p.reference=ref;if(engine.referenceGain)engine.referenceGain.gain.setTargetAtTime(10**(ref.gainDb/20),engine.ctx.currentTime,.02);d.save();};
  document.getElementById('listenMix').onclick=async()=>{try{engine.pause();engine.position=mixStart*16;engine.patternMode=null;engine.clipPreview=null;engine.takePreview=null;await engine.play();d.updateTransport();document.getElementById('referenceStatus').textContent='Écoute : mon mix';}catch(error){d.toast(error.message);}};
  document.getElementById('listenReference').onclick=async()=>{try{await engine.init();engine.playReference(a().buffer,{offset:ref.start,gainDb:ref.gainDb});d.updateTransport();document.getElementById('referenceStatus').textContent='Écoute : référence';}catch(error){d.toast(error.message);}};
  document.getElementById('stopReference').onclick=()=>{engine.pause();d.updateTransport();};
  document.getElementById('matchReference').onclick=async e=>{const button=e.currentTarget;button.disabled=true;const status=document.getElementById('referenceStatus');status.textContent='Mesure des quatre mesures…';try{const duration=Math.min(4,p.bars-mixStart)*240/p.bpm,buffer=await engine.renderRange({sampleRate:44100,startBar:mixStart,endBar:Math.min(p.bars,mixStart+4),tail:false}),mix=bufferRms(buffer,0,duration),reference=bufferRms(a().buffer,ref.start,duration);if(mix<.0001||reference<.0001)throw Error('Choisis un passage audible dans le mix et la référence.');if(d.getProject()!==p)throw Error('La session a changé pendant la mesure.');d.checkpoint();ref.gainDb=Math.max(-18,Math.min(18,20*Math.log10(mix/reference)));p.reference=ref;d.save();if(button.isConnected){document.getElementById('referenceLevel').value=ref.gainDb.toFixed(1);status.textContent='Niveau moyen ajusté : '+ref.gainDb.toFixed(1)+' dB. Écoute et affine si nécessaire.';}if(engine.referenceGain)engine.referenceGain.gain.setTargetAtTime(10**(ref.gainDb/20),engine.ctx.currentTime,.02);}catch(error){if(status.isConnected)status.textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}};
 }
 render();document.getElementById('modal').addEventListener('close',()=>engine.stopReference(),{once:true});
}
